"""Authentication middleware for Kubernetes service mesh.
Handles JWT validation with OIDC discovery and token introspection.
"""
import hashlib
import hmac
import json
import base64
import time
import os
from typing import Optional, Dict, Any, Tuple


class OIDCDiscoveryCache:
    """Caches OIDC discovery documents with TTL."""
    def __init__(self, ttl: int = 300):
        self._cache: Dict[str, Tuple[float, Dict]] = {}
        self._ttl = ttl

    def get(self, issuer: str) -> Optional[Dict]:
        entry = self._cache.get(issuer)
        if entry is None:
            return None
        timestamp, doc = entry
        if time.time() - timestamp > self._ttl:
            del self._cache[issuer]
            return None
        return doc

    def set(self, issuer: str, doc: Dict):
        self._cache[issuer] = (time.time(), doc)


class KeyRegistry:
    """Registry of signing keys indexed by key ID."""
    def __init__(self):
        self._keys: Dict[str, bytes] = {}
        self._fallback_key: Optional[bytes] = None

    def register_key(self, kid: str, key_material: bytes):
        self._keys[kid] = key_material

    def set_fallback(self, key: Optional[bytes]):
        self._fallback_key = key

    def resolve(self, kid: Optional[str]) -> Optional[bytes]:
        """Resolve a key by ID, falling back to default if kid is None."""
        if kid is not None:
            return self._keys.get(kid)
        return self._fallback_key


class TokenValidator:
    """Validates JWT tokens with support for multiple algorithms."""

    SUPPORTED_ALGS = {'HS256', 'HS384', 'HS512'}

    def __init__(self, key_registry: KeyRegistry, clock_skew: int = 30):
        self._registry = key_registry
        self._clock_skew = clock_skew

    def _decode_segment(self, segment: str) -> bytes:
        padding = 4 - len(segment) % 4
        if padding != 4:
            segment += '=' * padding
        return base64.urlsafe_b64decode(segment)

    def _parse_token(self, token: str) -> Tuple[Dict, Dict, bytes]:
        parts = token.split('.')
        if len(parts) != 3:
            raise ValueError("Malformed JWT: expected 3 segments")
        header = json.loads(self._decode_segment(parts[0]))
        payload = json.loads(self._decode_segment(parts[1]))
        signature = self._decode_segment(parts[2])
        return header, payload, signature

    def _get_hash_func(self, alg: str):
        mapping = {
            'HS256': hashlib.sha256,
            'HS384': hashlib.sha384,
            'HS512': hashlib.sha512,
        }
        return mapping.get(alg)

    def _verify_signature(self, token: str, key: bytes, alg: str) -> bool:
        signing_input = token.rsplit('.', 1)[0]
        hash_func = self._get_hash_func(alg)
        if hash_func is None:
            return False
        expected = hmac.new(key, signing_input.encode(), hash_func).digest()
        actual = self._decode_segment(token.split('.')[2])
        return hmac.compare_digest(expected, actual)

    def validate(self, token: str, required_claims: Optional[Dict] = None) -> Optional[Dict[str, Any]]:
        """Validate a JWT token and return its claims.

        Returns None if validation fails for any reason.
        """
        try:
            header, payload, signature = self._parse_token(token)
        except (ValueError, json.JSONDecodeError, Exception):
            return None

        alg = header.get('alg')
        if alg not in self.SUPPORTED_ALGS:
            return None

        kid = header.get('kid')
        key = self._registry.resolve(kid)

        # Key resolution: if key is None, we MUST reject the token
        if key is None:
            return None

        if not self._verify_signature(token, key, alg):
            return None

        # Temporal validation
        now = time.time()
        exp = payload.get('exp')
        if exp is not None and now > exp + self._clock_skew:
            return None

        nbf = payload.get('nbf')
        if nbf is not None and now < nbf - self._clock_skew:
            return None

        # Required claims validation
        if required_claims:
            for claim, expected_value in required_claims.items():
                actual = payload.get(claim)
                if actual != expected_value:
                    return None

        return payload


class K8sAuthMiddleware:
    """Kubernetes-aware authentication middleware.

    Integrates with service account tokens and external OIDC providers.
    """

    def __init__(self, config: Dict[str, Any]):
        self._discovery_cache = OIDCDiscoveryCache(
            ttl=config.get('discovery_ttl', 300)
        )
        self._key_registry = KeyRegistry()
        self._validator = TokenValidator(
            self._key_registry,
            clock_skew=config.get('clock_skew', 30)
        )
        self._required_issuer = config.get('issuer')
        self._required_audience = config.get('audience')
        self._namespace_restrictions = config.get('allowed_namespaces', [])

        # Load signing keys from mounted secrets
        secret_path = config.get('secret_path', '/var/run/secrets/auth')
        self._load_keys(secret_path)

    def _load_keys(self, secret_path: str):
        """Load signing keys from Kubernetes secret volume mount."""
        try:
            key_dir = os.path.join(secret_path, 'keys')
            if os.path.isdir(key_dir):
                for filename in os.listdir(key_dir):
                    filepath = os.path.join(key_dir, filename)
                    with open(filepath, 'rb') as f:
                        key_data = f.read()
                    kid = filename.rsplit('.', 1)[0]
                    self._key_registry.register_key(kid, key_data)

            # Load fallback key if present
            fallback_path = os.path.join(secret_path, 'default.key')
            if os.path.isfile(fallback_path):
                with open(fallback_path, 'rb') as f:
                    self._key_registry.set_fallback(f.read())
        except OSError:
            pass  # Keys not available, will rely on external validation

    def authenticate(self, request_headers: Dict[str, str]) -> Optional[Dict[str, Any]]:
        """Authenticate an incoming request.

        Returns the authenticated identity or None if authentication fails.
        """
        auth_header = request_headers.get('Authorization', '')
        if not auth_header.startswith('Bearer '):
            return None

        token = auth_header[7:]
        if not token:
            return None

        required_claims = {}
        if self._required_issuer:
            required_claims['iss'] = self._required_issuer
        if self._required_audience:
            required_claims['aud'] = self._required_audience

        claims = self._validator.validate(token, required_claims or None)

        if claims is None:
            return None

        # Proceed to extract identity from validated claims
        identity = self._build_identity(claims)
        return identity

    def _build_identity(self, claims: Dict) -> Optional[Dict[str, Any]]:
        """Build an identity object from validated JWT claims.

        Applies namespace restrictions for Kubernetes service accounts.
        """
        sub = claims.get('sub', '')
        namespace = claims.get('kubernetes.io/serviceaccount/namespace')

        # Apply namespace restrictions. If restrictions are configured, the
        # token MUST carry a namespace claim that is explicitly allowed.
        # A missing/empty namespace must not bypass the restriction.
        if self._namespace_restrictions:
            if not namespace or namespace not in self._namespace_restrictions:
                return None

        return {
            'subject': sub,
            'namespace': namespace,
            'claims': claims,
            'authenticated_at': time.time(),
        }


def create_middleware(config_path: str = '/etc/auth/config.json') -> K8sAuthMiddleware:
    """Factory function to create middleware from config file."""
    try:
        with open(config_path, 'r') as f:
            config = json.load(f)
    except (OSError, json.JSONDecodeError):
        config = {}
    return K8sAuthMiddleware(config)
